internal static class Supplement
{
 static string connection="",output="",marker="";static readonly List<object> results=[];
 static SessionContext admin=null!;static EmployeeService employees=null!;static EmployeeAccountService accounts=null!;static AttendanceService attendance=null!;static PayrollService payroll=null!;static AuthRepository auth=null!;
 static readonly DateTime day=new(2026,8,10);
 static SqlParameter P(string n,object v)=>v is decimal d?new(n,SqlDbType.Decimal){Precision=38,Scale=18,Value=d}:new(n,v);
 static async Task<SqlConnection> Open(bool runtime=false){var c=new SqlConnection(connection);await c.OpenAsync();if(runtime){using var q=c.CreateCommand();q.CommandText="EXECUTE AS USER='G06Runtime';";await q.ExecuteNonQueryAsync();}return c;}
 static async Task<object?> Owner(string sql,params SqlParameter[] ps){await using var c=await Open();using var q=c.CreateCommand();q.CommandText=sql;q.Parameters.AddRange(ps);return await q.ExecuteScalarAsync();}
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 static int Num(Exception e)=>e switch{UserOperationException u=>u.Error.Number,DataAccessException d=>d.Error.Number,SqlException s=>s.Number,ArgumentException=>-100,IOException=>-200,CryptographicException=>-201,_=>0};
 static async Task<int> Rejected(Func<Task> call,params int[] errors){try{await call();}catch(Exception e){if(errors.Contains(Num(e)))return Num(e);throw;}throw new Exception("Expected rejection, actual success");}
 static async Task Test(string id,string sub,string expected,Func<Task<object?>> call){try{var actual=await call();results.Add(new{Id=id,Subcase=sub,Expected=expected,Actual=actual,Status="PASS"});}catch(Exception e){results.Add(new{Id=id,Subcase=sub,Expected=expected,Actual=e.Message,Error=Num(e),Status="FAIL"});}File.WriteAllText(output,JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(id+" "+sub);}
 static async Task<string> Emp(string kind="Part-time",decimal month=0,decimal hour=35000)=>await employees.SaveAsync(admin,new("Fixture bổ sung",null,kind,month,hour,"CV002"),null,Guid.NewGuid());
 static async Task<EmployeeRow> Row(string c)=>await employees.GetAsync(admin,c)??throw new Exception("Missing fixture employee");
 static AttendanceLine L(string c,DateTime d,string shift="CA001",int start=8,int end=16)=>new(1,"Insert",c,d,shift,d.AddHours(start),d.AddHours(end),"Di lam",null);
 static async Task<PayrollRow> Close(PayrollRequest r){var p=await payroll.PreviewAsync(admin,r);Check(p.Snapshot.Issues.Count==0,"Preview issues");var id=int.Parse(await payroll.CommitAsync(admin,r with{Regular=p.Snapshot.RegularHours,Allowance=p.Snapshot.Allowance},p.Token,Guid.NewGuid()));return (await payroll.GetAsync(admin,id))!;}
 static async Task<object> Race(string resource,Func<Task> one,Func<Task> two){await using var gate=await Open();using var tx=gate.BeginTransaction();using var cmd=gate.CreateCommand();cmd.Transaction=tx;cmd.CommandText="DECLARE @r int;EXEC @r=sys.sp_getapplock @Resource=@n,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=1000;SELECT @r;";cmd.Parameters.AddWithValue("@n",resource);Check(Convert.ToInt32(await cmd.ExecuteScalarAsync())>=0,"Gate unavailable");async Task<int> Invoke(Func<Task> f){try{await f();return 0;}catch(Exception e){return Num(e);}}var a=Invoke(one);var b=Invoke(two);int wait=0;for(var i=0;i<35;i++){wait=Convert.ToInt32(await Owner("SELECT COUNT(*) FROM sys.dm_exec_requests WHERE database_id=DB_ID() AND wait_type IS NOT NULL AND session_id<>@@SPID"));if(wait>=2)break;await Task.Delay(100);}tx.Commit();var codes=await Task.WhenAll(a,b);Check(wait>=2&&codes.Count(x=>x==0)==1,"Race expected one success; actual "+string.Join(',',codes));return new{Waiters=wait,Results=codes};}
 public static async Task Main(string[] args)
 {
  if(args.Length==5&&args[0]=="read-pending"){var pending=new PendingOperationFile(args[1]).Read(int.Parse(args[2]),args[3]);Console.WriteLine(pending?.RequestId.ToString()==args[4]?"MATCH":"MISMATCH");return;}
  if(args.Length!=3||!System.Text.RegularExpressions.Regex.IsMatch(args[0],@"^CoffeeManager_Test_G06_\d{8}_\d{6}_[a-f0-9]{8}_demo$"))throw new ArgumentException("Test target required");
  marker=args[1];output=args[2];connection=new SqlConnectionStringBuilder{DataSource="localhost",InitialCatalog=args[0],IntegratedSecurity=true,Encrypt=true,TrustServerCertificate=true,Pooling=false,ApplicationName="G06Supplement"}.ConnectionString;
  Check(Convert.ToString(await Owner("SELECT RunId FROM dbo.G06TestMarker"))==marker,"Marker mismatch");
  var factory=new ConnectionFactory(connection);typeof(ConnectionFactory).GetProperty("SessionInitializer",BindingFlags.Instance|BindingFlags.NonPublic)!.SetValue(factory,(Func<SqlConnection,CancellationToken,Task>)(async(c,t)=>{using var q=c.CreateCommand();q.CommandText="EXECUTE AS USER='G06Runtime';";await q.ExecuteNonQueryAsync(t);}));
  auth=new(factory);var permissions=new PermissionService(auth);admin=new((await auth.ReadIdentityAsync(1,default))!);employees=new(new(factory),permissions);accounts=new(new(factory),permissions,new());attendance=new(new(factory),permissions);payroll=new(new(factory),new(factory),permissions);
  await Test24();await Test25();await Test26();await Pending();admin.Dispose();
 }
 static async Task Test24()
 {
  await Test("T24-K02","Name50Phone15MaxMoney","Valid upper boundaries preserved",async()=>{var c=await employees.SaveAsync(admin,new(new string('x',50),"123456789012345","Full-time",999999999999999999m,0,"CV001"),null,Guid.NewGuid());var r=await Row(c);Check(r.Name.Length==50&&r.Phone?.Length==15&&r.MonthlyRate==999999999999999999m,"Boundary truncated");return new{r.Code,NameLength=r.Name.Length,PhoneLength=r.Phone.Length,r.MonthlyRate};});
  await Test("T24-K03","AccountTwoSessions","Same employee two accounts: exactly one succeeds",async()=>{var c=await Emp();var pw=Guid.NewGuid().ToString("N");return await Race("CoffeeManager.AdminBootstrap",()=>accounts.WriteAsync(admin,"Create",new(c,null,"race.one","CASH",true),pw,pw,Guid.NewGuid()),()=>accounts.WriteAsync(admin,"Create",new(c,null,"race.two","CASH",true),pw,pw,Guid.NewGuid()));});
  foreach(var length in new[]{7,8,128,129})await Test("T24-K04","PasswordLength"+length,"8/128 accepted;7/129 rejected",async()=>{var c=await Emp();var pw=new string('x',length);if(length is 7 or 129)return await Rejected(()=>accounts.WriteAsync(admin,"Create",new(c,null,"length"+length,"CASH",true),pw,pw,Guid.NewGuid()),-100);await accounts.WriteAsync(admin,"Create",new(c,null,"length"+length,"CASH",true),pw,pw,Guid.NewGuid());return "Accepted";});
  await Test("T24-K04","ConfirmationMismatch","Different confirmation rejected",async()=>{var c=await Emp();return await Rejected(()=>accounts.WriteAsync(admin,"Create",new(c,null,"confirm.bad","CASH",true),"12345678","87654321",Guid.NewGuid()),-100);});
  await Test("T24-K06","LastAdminDeleteAndDemote","Last admin delete/demote denied; state remains active",async()=>{var r=await Row("NV001");var a=await Rejected(()=>employees.DeleteAsync(admin,r,Guid.NewGuid()),547,53102);var b=await Rejected(()=>accounts.WriteAsync(admin,"Change",new(r.Code,r.AccountStamp,null,"CASH",true),null,null,Guid.NewGuid()),53102);Check((await Row("NV001")).Role=="ADMIN","Last ADMIN changed");return new{Delete=a,Demote=b};});
  foreach(var id in new[]{2,3})await Test("T24-K07","LowPrivilegeWrite"+id,"Active CASH/STORE cannot change role or employee",async()=>{using var s=new SessionContext((await auth.ReadIdentityAsync(id,default))!);Check(s.Identity.Active&&s.Identity.Employed,"Actor inactive");var r=await Row("NV002");var a=await Rejected(()=>employees.SaveAsync(s,new(r.Name,r.Phone,r.Contract,r.MonthlyRate,r.HourlyRate,r.Position),r,Guid.NewGuid()),51605);var b=await Rejected(()=>accounts.WriteAsync(s,"Change",new("NV001",admin.Identity.SecurityStamp,null,"CASH",true),null,null,Guid.NewGuid()),51605);return new{Role=s.Identity.Role,Employee=a,Account=b};});
  await Test("T24-K09","AccountAndInvoiceReferences","Account-linked/invoice-linked employees cannot delete",async()=>{var a=await Rejected(async()=>await employees.DeleteAsync(admin,await Row("NV004"),Guid.NewGuid()),547,53102);var b=await Rejected(async()=>await employees.DeleteAsync(admin,await Row("NV001"),Guid.NewGuid()),547,53102);return new{AccountReference=a,InvoiceReference=b};});
  await Test("T24-K10","FilterPagingAndVersion","Filtered payroll profile and stale version/receipt protected",async()=>{var c=await Emp();var r=await Row(c);var id=Guid.NewGuid();var created=await employees.SaveAsync(admin,new("Tên có dấu",null,"Part-time",0,35000,"CV002"),r,id);Check((await employees.ListAsync(admin,new("Tên có dấu",Contract:"Part-time",Employed:true))).Any(x=>x.Code==c),"Filter missed saved name");var stale=await Rejected(()=>employees.SaveAsync(admin,new("Ghi đè",null,r.Contract,0,0,r.Position),r,Guid.NewGuid()),53103);Check((await employees.ReceiptAsync(admin,id,"EmployeeUpdate"))?.Code==created,"Update receipt absent");return new{Stale=stale,Code=c};});
 }
 static async Task Test25()
 {
  await Test("T25-K03","LeaveValidIncompleteNoHours","Leave/absent without times valid; incomplete distinguished",async()=>{var c=await Emp();await attendance.SaveAsync(admin,[L(c,day) with{ClockIn=null,ClockOut=null,Status="Nghi phep"},L(c,day.AddDays(1)) with{RowNo=2,ClockIn=null,ClockOut=null,Status="Vang"},L(c,day.AddDays(2)) with{RowNo=3,ClockIn=null,ClockOut=null}],Guid.NewGuid());var list=await attendance.ListAsync(admin,new(8,2026,c));Check(list.Count==3&&list.Count(x=>x.Incomplete)==1,"Incomplete/leave mixed");return list.Select(x=>new{x.Status,x.Incomplete,x.Hours}).ToArray();});
  foreach(var mode in new[]{"Contained","Partial","CrossDay","Open"})await Test("T25-K04",mode,"Overlap rejected and no second row",async()=>{var c=await Emp();var first=L(c,day);if(mode=="CrossDay")first=first with{ClockIn=day.AddHours(22),ClockOut=day.AddDays(1).AddHours(6)};if(mode=="Open")first=first with{ClockOut=null};await attendance.SaveAsync(admin,[first],Guid.NewGuid());var second=mode=="CrossDay"?L(c,day.AddDays(1),"CA002",5,7):L(c,day,"CA002",mode=="Contained"?9:15,mode=="Contained"?10:17);return await Rejected(()=>attendance.SaveAsync(admin,[second],Guid.NewGuid()),53203);});
  await Test("T25-K05","OneSecondOverlap","One second overlap rejected; exact boundary accepted",async()=>{var c=await Emp();await attendance.SaveAsync(admin,[L(c,day)],Guid.NewGuid());var second=L(c,day,"CA002",16,20);await Rejected(()=>attendance.SaveAsync(admin,[second with{ClockIn=day.AddHours(16).AddSeconds(-1)}],Guid.NewGuid()),53203);await attendance.SaveAsync(admin,[second],Guid.NewGuid());return "Exact boundary accepted";});
  await Test("T25-K08","NewClosedAllMutations","New period rejects insert/update/delete and direct runtime DML",async()=>{var c=await Emp();await attendance.SaveAsync(admin,[L(c,day)],Guid.NewGuid());await Close(new(c,8,2026,8,0,0,0));var r=(await attendance.ListAsync(admin,new(8,2026,c))).Single();var old=new AttendanceLine(1,"Update",c,day,r.Shift,r.ClockIn,r.ClockOut,r.Status,r.Revision);var a=await Rejected(()=>attendance.SaveAsync(admin,[old],Guid.NewGuid()),53202);var b=await Rejected(()=>attendance.SaveAsync(admin,[old with{Action="Delete"}],Guid.NewGuid()),53202);var d=await Rejected(()=>attendance.SaveAsync(admin,[L(c,day.AddDays(1))],Guid.NewGuid()),53202);return new{Update=a,Delete=b,Insert=d};});
  await Test("T25-K10","FiltersReload","Employee/status/month filters return correct actual rows",async()=>{var c=await Emp();await attendance.SaveAsync(admin,[L(c,day),L(c,day.AddDays(1)) with{RowNo=2,ClockOut=null}],Guid.NewGuid());var complete=await attendance.ListAsync(admin,new(8,2026,c,"Complete"));var incomplete=await attendance.ListAsync(admin,new(8,2026,c,"Incomplete"));Check(complete.Count==1&&incomplete.Count==1&&complete[0].TotalRows==1,"Filter result mismatch");return new{Complete=complete.Count,Incomplete=incomplete.Count};});
  await Test("T25-K11","ValidBatchAndInternalOverlap","Valid two employees commit; overlapping same employee batch rolls back",async()=>{var a=await Emp();var b=await Emp();await attendance.SaveAsync(admin,[L(a,day),L(b,day) with{RowNo=2}],Guid.NewGuid());var c=await Emp();var id=Guid.NewGuid();await Rejected(()=>attendance.SaveAsync(admin,[L(c,day),L(c,day,"CA002",9,17) with{RowNo=2}],id),53203);Check((await attendance.ListAsync(admin,new(8,2026,c))).Count==0&&await attendance.ReceiptAsync(admin,id)==null,"Internal overlap partially persisted");return "Valid2rows; invalid0rows/receipt";});
 }
 static async Task Test26()
 {
  await Test("T26-K02","RoundSumOnce","Two36sec records total0.02h, not per-line0.01+0.01 altered",async()=>{var c=await Emp(hour:100);await attendance.SaveAsync(admin,[L(c,day) with{ClockOut=day.AddHours(8).AddSeconds(18)},L(c,day.AddDays(1)) with{RowNo=2,ClockOut=day.AddDays(1).AddHours(8).AddSeconds(18)}],Guid.NewGuid());var p=await payroll.PreviewAsync(admin,new(c,8,2026,Allowance:0));Check(p.Snapshot.TotalSeconds==36&&p.Snapshot.TotalHours==.01m&&p.Snapshot.Amount==1,"Total seconds not rounded once");return new{p.Snapshot.TotalSeconds,p.Snapshot.TotalHours,p.Snapshot.Amount};});
  await Test("T26-K03","DefensiveLegacyOverlapPreview","Raw fixture overlap reported and cannot commit",async()=>{var c=await Emp();await attendance.SaveAsync(admin,[L(c,day)],Guid.NewGuid());await Owner("INSERT dbo.CHAMCONG(MaNV,NgayLam,MaCa,GioVao,GioRa,TrangThai)VALUES(@c,'20260810','CA002','20260810 09:00','20260810 10:00',N'Di lam')",P("@c",c));var p=await payroll.PreviewAsync(admin,new(c,8,2026,Allowance:0));Check(p.Snapshot.Issues.Count>0,"Overlap not in issues");return await Rejected(()=>payroll.CommitAsync(admin,new(c,8,2026,p.Snapshot.RegularHours,0,0,0),p.Token,Guid.NewGuid()),53302);});
  await Test("T26-K04","SQLNullPeriodAndPrecision","SQL rejects invalid period/negative/precision outside BLL",async()=>{await using var c=await Open(true);using var q=c.CreateCommand();q.CommandText="EXEC dbo.sp_PayrollPreview @Actor=1,@Stamp=@s,@Employee='NV002',@Month=13,@Year=2026";q.Parameters.AddWithValue("@s",admin.Identity.SecurityStamp);try{await q.ExecuteNonQueryAsync();throw new Exception("SQL accepted month13");}catch(SqlException e){Check(e.Number==53301,"Unexpected SQL error");return e.Number;}});
  await Test("T26-K06","NoDataFullTimeAndRetiredHistory","No prorating; valid historical payroll for retired employee",async()=>{var c=await Emp("Full-time",1000000,0);await employees.EmploymentAsync(admin,await Row(c),false,Guid.NewGuid());var r=await Close(new(c,8,2026,0,0,0,0));Check(r.Amount==1000000&&r.Snapshot?.Employed==false,"Retired/no-data contract mismatch");return new{r.Amount,r.Snapshot!.Employed};});
  await Test("T26-K07","OwnerImmutableTriggers","Even owner UPDATE/DELETE of posted snapshot rejected",async()=>{var c=await Emp();var r=await Close(new(c,8,2026,0,0,0,0));var a=await Rejected(()=>Owner("UPDATE dbo.BANGLUONG SET Thuong=Thuong+1 WHERE MaBL=@i",P("@i",r.Id)),53302);var b=await Rejected(()=>Owner("DELETE dbo.BANGLUONG WHERE MaBL=@i",P("@i",r.Id)),53302);return new{Update=a,Delete=b};});
  await Timeout(false);await Timeout(true);
  await Test("T26-K10","ZeroDirectSql","Direct public SQL cannot create zero-valued expense",async()=>{var c=await Emp();var r=await Close(new(c,8,2026,0,0,0,0));await Task.Delay(1100);await using var sql=await Open(true);using var q=sql.CreateCommand();q.CommandText="EXEC dbo.sp_ChiLuong @Actor=1,@Stamp=@s,@RequestId=@r,@Id=@i,@Date=@d,@ExpectedAmount=0";q.Parameters.AddWithValue("@s",admin.Identity.SecurityStamp);q.Parameters.AddWithValue("@r",Guid.NewGuid());q.Parameters.AddWithValue("@i",r.Id);var now=DateTime.Now;q.Parameters.AddWithValue("@d",now.AddTicks(-(now.Ticks%TimeSpan.TicksPerSecond)));try{await q.ExecuteNonQueryAsync();throw new Exception("SQL paid zero net");}catch(SqlException e){Check(e.Number==53302,"Unexpected zero error");return e.Number;}});
 }
 static async Task Timeout(bool afterCommit)
 {
  await Test("T26-K12",afterCommit?"TimeoutAfterCommit":"TimeoutBeforeCommit",afterCommit?"Expense committed once; receipt and replay identify result":"Before-commit timeout does not persist payroll payment",async()=>{
   var c=await Emp();await attendance.SaveAsync(admin,[L(c,day)],Guid.NewGuid());var r=await Close(new(c,8,2026,8,0,0,0));await Task.Delay(1100);var request=Guid.NewGuid();var now=DateTime.Now;now=now.AddTicks(-(now.Ticks%TimeSpan.TicksPerSecond));
   SqlConnection? gate=null;SqlTransaction? tx=null;
   try{
    if(!afterCommit){gate=await Open();tx=gate.BeginTransaction();using var g=gate.CreateCommand();g.Transaction=tx;g.CommandText="EXEC sys.sp_getapplock @Resource=@n,@LockMode='Exclusive',@LockOwner='Transaction'";g.Parameters.AddWithValue("@n","CafeManager:HR:Employee:"+c);await g.ExecuteNonQueryAsync();}
    await using(var sql=await Open(true)){using var q=sql.CreateCommand();q.CommandTimeout=1;q.CommandText="EXEC dbo.sp_ChiLuong @Actor=1,@Stamp=@s,@RequestId=@r,@Id=@i,@Date=@d,@ExpectedAmount=@a;"+(afterCommit?"WAITFOR DELAY '00:00:03';":"");q.Parameters.AddWithValue("@s",admin.Identity.SecurityStamp);q.Parameters.AddWithValue("@r",request);q.Parameters.AddWithValue("@i",r.Id);q.Parameters.AddWithValue("@d",now);q.Parameters.Add(P("@a",r.Amount));try{await q.ExecuteNonQueryAsync();throw new Exception("Timeout not observed");}catch(SqlException e){Check(e.Number==-2,"Expected client timeout");}}
   }finally{if(tx is not null){tx.Commit();tx.Dispose();}if(gate is not null)await gate.DisposeAsync();}
   var receipt=await payroll.ReceiptAsync(admin,request,"PayrollPay");var actual=(await payroll.GetAsync(admin,r.Id))!;
   Check(afterCommit?receipt?.Code==r.Id.ToString()&&actual.Status=="Paid":receipt is null&&actual.Status=="Unpaid","Timeout persistence differs");
   if(afterCommit)await payroll.PayAsync(admin,r,now,request);
   var count=Convert.ToInt32(await Owner("SELECT COUNT(*) FROM dbo.PHIEUTHUCHI WHERE MaBL=@i",P("@i",r.Id)));Check(count==(afterCommit?1:0),"Duplicate/stray expense");return new{AfterCommit=afterCommit,ClientError=-2,ExpenseCount=count,Receipt=receipt?.Code,actual.Status};
  });
 }
 static async Task Pending()
 {
  var context=await employees.ContextAsync(admin);var scope=context.Scope+"|acceptance:"+marker;var store=new PendingOperationFile(scope);var operation="G06AcceptancePending";var id=Guid.NewGuid();
  var prefix=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(scope)));var path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CoffeeManager","Pending",$"{prefix}_1_{operation}.bin");
  try{
   await Test("T26-K12","PendingScopeAndDoubleSend","DPAPI roundtrip; another DB scope cannot read; second request not overwrite",async()=>{store.Save(new(1,id,operation,"synthetic payroll request",DateTime.UtcNow));Check(store.Read(1,operation)?.RequestId==id,"Pending roundtrip failed");Check(new PendingOperationFile(scope+"other").Read(1,operation)==null,"Cross-scope pending visible");var n=await Rejected(()=>Task.Run(()=>store.Save(new(1,Guid.NewGuid(),operation,"other",DateTime.UtcNow))),-200);return new{Roundtrip=true,CrossScopeMissing=true,OverwriteError=n};});
   await Test("T26-K12","PendingNewProcess","New process same Windows user reads protected pending request",async()=>{var exe=Environment.ProcessPath!;var info=new System.Diagnostics.ProcessStartInfo(exe){UseShellExecute=false,RedirectStandardOutput=true,CreateNoWindow=true};foreach(var a in new[]{"read-pending",scope,"1",operation,id.ToString()})info.ArgumentList.Add(a);using var p=System.Diagnostics.Process.Start(info)!;var text=await p.StandardOutput.ReadToEndAsync();await p.WaitForExitAsync();Check(p.ExitCode==0&&text.Trim()=="MATCH","Restart pending not recovered");return "MATCH";});
   await Test("T26-K12","CorruptPending","Corrupted DPAPI file reports error instead of silent reset",async()=>{File.WriteAllBytes(path,[1,2,3]);return await Rejected(()=>Task.Run(()=>store.Read(1,operation)),-201);});
  }finally{foreach(var f in new[]{path,path+".lock",path+".tmp"})if(File.Exists(f))File.Delete(f);}
 }
}
